//! Raw, unsafe FFI bindings to `libzxv` (`sdk/libzxv/include/zxv_api.h`).
//!
//! These are generated by bindgen and checked in (`src/bindings.rs`), so a
//! normal build needs no libclang. Rebuild them with
//! `cargo build -p zxv-sys --features regenerate`.
//!
//! Use the safe [`zxv`](https://docs.rs/zxv) crate instead of this one. The
//! function-like macros of the header (the `ZXV_CAP_*` capability bits and
//! `ZXV_AMOUNT_MAX`) are not visible to bindgen and are defined by hand
//! below.
#![no_std]
#![allow(non_camel_case_types, non_upper_case_globals, non_snake_case)]
#![allow(clippy::all)]
#![allow(rustdoc::all)]

include!("bindings.rs");

/// Read balances and journals.
pub const ZXV_CAP_LEDGER_READ: u64 = 1 << 0;
/// Post transfers.
pub const ZXV_CAP_LEDGER_POST: u64 = 1 << 1;
/// Sign with ML-DSA / Ed25519.
pub const ZXV_CAP_CRYPTO_SIGN: u64 = 1 << 2;
/// ML-KEM encapsulation.
pub const ZXV_CAP_CRYPTO_KEM: u64 = 1 << 3;
/// Model loading and generation.
pub const ZXV_CAP_AI_INFERENCE: u64 = 1 << 4;
/// Resource budgets.
pub const ZXV_CAP_BUDGET: u64 = 1 << 5;
/// Phase clock admit / defer / advance.
pub const ZXV_CAP_PHASE: u64 = 1 << 6;
/// Attestations.
pub const ZXV_CAP_ATTEST: u64 = 1 << 7;
/// Swarm economy.
pub const ZXV_CAP_SWARM: u64 = 1 << 8;
/// EVM state-channel encoding.
pub const ZXV_CAP_EVM: u64 = 1 << 9;
/// Every capability bit.
pub const ZXV_CAP_ALL: u64 = (1 << 10) - 1;
/// Largest amount in one posting (2^53 - 1).
pub const ZXV_AMOUNT_MAX: i64 = 9007199254740991;
